static void test_x509_parse(void) {
    neverc_x509_cert_t cert;
    int rc = neverc_x509_parse_certificate(&cert, test_cert_der, sizeof(test_cert_der));
    CHECK("parse_success", rc == 0);

    CHECK("version_v3", cert.version == 2);
    CHECK("serial_len_20", cert.serial_len == 20);

    CHECK("sig_algo_sha256_rsa", cert.sig_algorithm == NEVERC_X509_SIG_SHA256_RSA);
    CHECK("key_algo_rsa", cert.key_algorithm == NEVERC_X509_KEY_RSA);

    CHECK("issuer_country", strcmp(cert.issuer.country, "US") == 0);
    CHECK("issuer_org", strcmp(cert.issuer.organization, "NeverC Test") == 0);
    CHECK("issuer_cn", strcmp(cert.issuer.common_name, "test.neverc.dev") == 0);

    CHECK("subject_country", strcmp(cert.subject.country, "US") == 0);
    CHECK("subject_org", strcmp(cert.subject.organization, "NeverC Test") == 0);
    CHECK("subject_cn", strcmp(cert.subject.common_name, "test.neverc.dev") == 0);

    CHECK("not_before_year", cert.not_before.year == 2026);
    CHECK("not_before_month", cert.not_before.month == 6);
    CHECK("not_before_day", cert.not_before.day == 7);
    CHECK("not_after_year", cert.not_after.year == 2036);
    CHECK("not_after_month", cert.not_after.month == 6);
    CHECK("not_after_day", cert.not_after.day == 4);

    CHECK("has_public_key", cert.public_key != NULL && cert.public_key_len > 0);
    CHECK("is_ca", cert.is_ca == 1);
    CHECK("is_self_signed", neverc_x509_is_self_signed(&cert) == 1);

    neverc_x509_cert_free(&cert);
}

static void test_x509_strings(void) {
    CHECK("sig_sha256_rsa", strcmp(neverc_x509_sig_algorithm_string(NEVERC_X509_SIG_SHA256_RSA),
                                   "SHA256-RSA") == 0);
    CHECK("sig_ecdsa_sha256", strcmp(neverc_x509_sig_algorithm_string(NEVERC_X509_SIG_ECDSA_SHA256),
                                     "ECDSA-SHA256") == 0);
    CHECK("sig_ed25519", strcmp(neverc_x509_sig_algorithm_string(NEVERC_X509_SIG_ED25519),
                                 "Ed25519") == 0);
    CHECK("key_rsa", strcmp(neverc_x509_key_algorithm_string(NEVERC_X509_KEY_RSA),
                             "RSA") == 0);
    CHECK("key_ecdsa", strcmp(neverc_x509_key_algorithm_string(NEVERC_X509_KEY_ECDSA),
                               "ECDSA") == 0);
}

static void test_x509_time_compare(void) {
    neverc_x509_time_t t1 = {2024, 1, 1, 0, 0, 0};
    neverc_x509_time_t t2 = {2034, 12, 31, 23, 59, 59};
    neverc_x509_time_t t3 = {2024, 1, 1, 0, 0, 0};

    CHECK("time_before", neverc_x509_time_compare(&t1, &t2) < 0);
    CHECK("time_after", neverc_x509_time_compare(&t2, &t1) > 0);
    CHECK("time_equal", neverc_x509_time_compare(&t1, &t3) == 0);
}

static void test_x509_format_name(void) {
    neverc_x509_name_t name;
    memset(&name, 0, sizeof(name));
    strcpy(name.country, "US");
    strcpy(name.organization, "NeverC Test");
    strcpy(name.common_name, "test.neverc.dev");

    char buf[512];
    int n = neverc_x509_format_name(&name, buf, sizeof(buf));
    CHECK("format_name_success", n > 0);
    CHECK("format_has_country", strstr(buf, "C=US") != NULL);
    CHECK("format_has_org", strstr(buf, "O=NeverC Test") != NULL);
    CHECK("format_has_cn", strstr(buf, "CN=test.neverc.dev") != NULL);
}

static void test_x509_invalid(void) {
    neverc_x509_cert_t cert;
    uint8_t garbage[] = {0x00, 0x01, 0x02, 0x03};
    int rc = neverc_x509_parse_certificate(&cert, garbage, sizeof(garbage));
    CHECK("invalid_fails", rc < 0);
}

int main(void) {
    printf("=== NeverC crypto/x509 Tests ===\n\n");

    test_x509_parse();
    test_x509_strings();
    test_x509_time_compare();
    test_x509_format_name();
    test_x509_invalid();

    printf("\n%d/%d tests passed", tests_passed, tests_run);
    if (tests_failed > 0)
        printf(", %d FAILED", tests_failed);
    printf("\n");
    return tests_failed > 0 ? 1 : 0;
}
